import runpy
import sys

s = runpy.run_path(sys.argv[1])
w = s['Wallet'](5)
for bad in [7, 0, -1, True, False, 1.5, '2', None]:
    try:
        w.withdraw(bad)
    except ValueError:
        pass
    else:
        raise AssertionError('invalid withdrawal accepted')
    assert w.balance == 5
assert w.withdraw(2) == 3
assert w.withdraw(3) == 0
try:
    w.withdraw(1)
except ValueError:
    pass
else:
    raise AssertionError('overdraw accepted')
assert w.balance == 0
